import{_ as s,o as n,c as p,ag as t}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"毛泽东哲学名篇详细分析（入门版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/mao-zedong/mao-philosophy-practice-contradiction.md","filePath":"topics/mao-zedong/mao-philosophy-practice-contradiction.md"}'),l={name:"topics/mao-zedong/mao-philosophy-practice-contradiction.md"};function e(i,a,o,c,r,d){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="毛泽东哲学名篇详细分析-入门版" tabindex="-1">毛泽东哲学名篇详细分析（入门版） <a class="header-anchor" href="#毛泽东哲学名篇详细分析-入门版" aria-label="Permalink to &quot;毛泽东哲学名篇详细分析（入门版）&quot;">​</a></h1><blockquote><p>对应《毛泽东文集》核心哲学著作：《实践论》《矛盾论》的逐篇深度解析 适合：想学哲学思维、提升分析能力的读者 难度：入门级，有高中文化基础即可读懂</p></blockquote><hr><h2 id="一、先搞清楚-毛泽东哲学在整座哲学大厦里的位置" tabindex="-1">一、先搞清楚：毛泽东哲学在整座哲学大厦里的位置 <a class="header-anchor" href="#一、先搞清楚-毛泽东哲学在整座哲学大厦里的位置" aria-label="Permalink to &quot;一、先搞清楚：毛泽东哲学在整座哲学大厦里的位置&quot;">​</a></h2><h3 id="哲学地图-快速定位" tabindex="-1">哲学地图（快速定位） <a class="header-anchor" href="#哲学地图-快速定位" aria-label="Permalink to &quot;哲学地图（快速定位）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>哲学</span></span>
<span class="line"><span>├── 世界观（世界是什么）</span></span>
<span class="line"><span>│   ├── 唯物论：物质第一性，意识第二性</span></span>
<span class="line"><span>│   └── 唯心论：意识第一性，物质第二性</span></span>
<span class="line"><span>├── 认识论（人怎么认识世界）</span></span>
<span class="line"><span>│   ├── 唯理论（理性先于经验）</span></span>
<span class="line"><span>│   └── 经验论（经验先于理性）</span></span>
<span class="line"><span>│       └── 辩证唯物主义：实践是认识的基础 ← 毛泽东《实践论》</span></span>
<span class="line"><span>├── 辩证法（世界怎么运行）</span></span>
<span class="line"><span>│   ├── 形而上学：孤立、静止、片面地看问题</span></span>
<span class="line"><span>│   └── 唯物辩证法：联系、发展、全面地看问题</span></span>
<span class="line"><span>│       └── 三大规律：对立统一、质量互变、否定之否定</span></span>
<span class="line"><span>│           └── 核心规律：对立统一（矛盾）← 毛泽东《矛盾论》</span></span>
<span class="line"><span>└── 历史观（社会怎么运行）</span></span>
<span class="line"><span>    └── 唯物史观：生产力与生产关系、经济基础与上层建筑</span></span></code></pre></div><p><strong>毛泽东哲学的定位：</strong></p><ul><li>马克思（创立者）+ 恩格斯 + 列宁（发展）+ <strong>毛泽东（中国化落地）</strong></li><li>核心贡献：<strong>把哲学从书本上拉下来，直接用来干革命</strong></li><li>两篇代表作：《实践论》（认识论）、《矛盾论》（辩证法）</li></ul><hr><h2 id="二、《实践论》-人是怎么认识世界的" tabindex="-1">二、《实践论》：人是怎么认识世界的 <a class="header-anchor" href="#二、《实践论》-人是怎么认识世界的" aria-label="Permalink to &quot;二、《实践论》：人是怎么认识世界的&quot;">​</a></h2><h3 id="_2-1-一句话核心" tabindex="-1">2.1 一句话核心 <a class="header-anchor" href="#_2-1-一句话核心" aria-label="Permalink to &quot;2.1 一句话核心&quot;">​</a></h3><blockquote><p><strong>认识从实践中来，到实践中去。实践是认识的起点，也是认识的终点。</strong></p></blockquote><h3 id="_2-2-原文精读-认识的两个阶段" tabindex="-1">2.2 原文精读：认识的两个阶段 <a class="header-anchor" href="#_2-2-原文精读-认识的两个阶段" aria-label="Permalink to &quot;2.2 原文精读：认识的两个阶段&quot;">​</a></h3><p><strong>第一阶段：感性认识（初级阶段）</strong></p><p>原文：</p><blockquote><p>&quot;原来人在实践过程中，开始只是看到过程中各个事物的现象方面，看到它们的外部联系……这叫做认识的感性阶段。&quot;</p></blockquote><p><strong>通俗理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你看到：</span></span>
<span class="line"><span>- 天空乌云密布（现象）</span></span>
<span class="line"><span>- 风吹得树叶乱晃（现象）</span></span>
<span class="line"><span>- 空气闷热（现象）</span></span>
<span class="line"><span>↓ 这些都是事物的外部、表面、片面的认识</span></span>
<span class="line"><span>= 感性认识</span></span></code></pre></div><p><strong>第二阶段：理性认识（高级阶段）</strong></p><p>原文：</p><blockquote><p>&quot;社会实践的继续，使人们在实践中引起感觉和印象的东西反复了多次，于是在人们的脑子里生起了一个认识过程中的突变（即飞跃），产生了概念……&quot;</p></blockquote><p><strong>通俗理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>多次看到同样现象 → 脑子里形成概念</span></span>
<span class="line"><span>乌云 + 闷热 + 树叶乱晃 → 抽象出&quot;要下雨了&quot;</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>这个抽象的判断和推理 = 理性认识</span></span></code></pre></div><h3 id="_2-3-认识过程的完整公式" tabindex="-1">2.3 认识过程的完整公式 <a class="header-anchor" href="#_2-3-认识过程的完整公式" aria-label="Permalink to &quot;2.3 认识过程的完整公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实践</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>接触外界事物（感性直观）</span></span>
<span class="line"><span>  ↓  （量变积累）</span></span>
<span class="line"><span>达到一个质的飞跃</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>形成概念和判断（理性认识）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>运用概念进行推理</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>指导实践（检验和修正认识）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>又回到实践……</span></span></code></pre></div><p>毛泽东原文最精彩的一段：</p><blockquote><p>&quot;通过实践而发现真理，又通过实践而证实真理和发展真理。从感性认识而能动地发展到理性认识，又从理性认识而能动地指导革命实践，改造主观世界和客观世界。&quot;</p></blockquote><h3 id="_2-4-关键区分-理性认识-凭空想象" tabindex="-1">2.4 关键区分：理性认识 ≠ 凭空想象 <a class="header-anchor" href="#_2-4-关键区分-理性认识-凭空想象" aria-label="Permalink to &quot;2.4 关键区分：理性认识 ≠ 凭空想象&quot;">​</a></h3><p><strong>错误做法（唯心论）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先想出一套理论</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>从书本出发，用理论套现实</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>符合理论的→接受，不符合的→否认</span></span></code></pre></div><p><strong>正确做法（辩证唯物论）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先从实际出发（调查研究）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>从实践中总结规律</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>形成理论</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>再到实践中检验和修正</span></span></code></pre></div><h3 id="_2-5-《实践论》的现实应用" tabindex="-1">2.5 《实践论》的现实应用 <a class="header-anchor" href="#_2-5-《实践论》的现实应用" aria-label="Permalink to &quot;2.5 《实践论》的现实应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>错误做法</th><th>正确做法</th></tr></thead><tbody><tr><td><strong>工作方案制定</strong></td><td>照搬其他公司模板，不看自己实际情况</td><td>先调研自己情况，从实践中总结规律</td></tr><tr><td><strong>学习投资</strong></td><td>看K线图预测明天涨跌（凭感觉）</td><td>了解公司基本面，理解商业模式（理性）</td></tr><tr><td><strong>做决策</strong></td><td>&quot;我觉得……&quot;、&quot;历史上……&quot;（拍脑袋）</td><td>实地调查、数据分析、试点验证</td></tr><tr><td><strong>学技能</strong></td><td>疯狂看书看教程，从不实操</td><td>边做边学，在实践中发现问题</td></tr></tbody></table><p><strong>核心口诀：</strong> 没有调查，没有发言权。不做正确的调查，同样没有发言权。</p><hr><h2 id="三、《矛盾论》-世界怎么运行的" tabindex="-1">三、《矛盾论》：世界怎么运行的 <a class="header-anchor" href="#三、《矛盾论》-世界怎么运行的" aria-label="Permalink to &quot;三、《矛盾论》：世界怎么运行的&quot;">​</a></h2><h3 id="_3-1-一句话核心" tabindex="-1">3.1 一句话核心 <a class="header-anchor" href="#_3-1-一句话核心" aria-label="Permalink to &quot;3.1 一句话核心&quot;">​</a></h3><blockquote><p><strong>矛盾就是问题。世界是由矛盾推动的。解决矛盾，就是解决问题。</strong></p></blockquote><h3 id="_3-2-矛盾是什么" tabindex="-1">3.2 矛盾是什么 <a class="header-anchor" href="#_3-2-矛盾是什么" aria-label="Permalink to &quot;3.2 矛盾是什么&quot;">​</a></h3><p><strong>最通俗的定义：</strong></p><blockquote><p>对立面的统一和斗争。</p></blockquote><p>什么意思？举个例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>药和病 = 一对矛盾</span></span>
<span class="line"><span>- 药要治病，病要抵抗</span></span>
<span class="line"><span>- 没有病，就不需要药；没有药，病就治不好</span></span>
<span class="line"><span>- 两者既对立（对着干），又统一（相互依存）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这对矛盾在医院里不断斗争</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>疾病被治好（旧的矛盾解决）</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>新的矛盾出现（又有新病）</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>推动医疗进步（事物发展）</span></span></code></pre></div><h3 id="_3-3-矛盾的两条性质" tabindex="-1">3.3 矛盾的两条性质 <a class="header-anchor" href="#_3-3-矛盾的两条性质" aria-label="Permalink to &quot;3.3 矛盾的两条性质&quot;">​</a></h3><p><strong>① 矛盾的普遍性</strong></p><p>原文：</p><blockquote><p>&quot;矛盾的普遍性或绝对性这个问题有两方面的意义。其一是说，矛盾存在于一切事物的发展过程中；其二是说，每一事物的发展过程中存在着自始至终的矛盾运动。&quot;</p></blockquote><p><strong>通俗版：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>矛盾无处不在：</span></span>
<span class="line"><span>- 自然界：遗传与变异、光合作用与呼吸作用</span></span>
<span class="line"><span>- 社会：生产力与生产关系、供给与需求</span></span>
<span class="line"><span>- 人体：新陈代谢、兴奋与抑制</span></span>
<span class="line"><span>- 工作：效率与质量、速度与安全</span></span>
<span class="line"><span>- 个人：理想与现实、理性与情感</span></span>
<span class="line"><span></span></span>
<span class="line"><span>矛盾无时不在：</span></span>
<span class="line"><span>- 一个过程结束了，旧矛盾解决了</span></span>
<span class="line"><span>- 新过程开始了，新矛盾又产生了</span></span>
<span class="line"><span>- 矛盾贯穿事物发展全过程</span></span></code></pre></div><p><strong>② 矛盾的特殊性</strong></p><p>原文：</p><blockquote><p>&quot;任何运动形式，其内部都包含着本身特殊的矛盾。这种特殊的矛盾，就构成一事物区别于他事物的特殊的本质。&quot;</p></blockquote><p><strong>通俗版：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>医生治病：</span></span>
<span class="line"><span>- 感冒的特殊矛盾 = 病毒/细菌 + 人体免疫力</span></span>
<span class="line"><span>- 骨折的特殊矛盾 = 外力冲击 + 骨骼结构</span></span>
<span class="line"><span>- 心脏病特殊矛盾 = 血管堵塞 + 心脏功能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个病的矛盾都不同</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>所以治法也不同</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>这就是&quot;具体问题具体分析&quot;</span></span></code></pre></div><h3 id="_3-4-矛盾分析的核心方法" tabindex="-1">3.4 矛盾分析的核心方法 <a class="header-anchor" href="#_3-4-矛盾分析的核心方法" aria-label="Permalink to &quot;3.4 矛盾分析的核心方法&quot;">​</a></h3><h4 id="方法一-抓主要矛盾" tabindex="-1">方法一：抓主要矛盾 <a class="header-anchor" href="#方法一-抓主要矛盾" aria-label="Permalink to &quot;方法一：抓主要矛盾&quot;">​</a></h4><p><strong>原文：</strong></p><blockquote><p>&quot;在复杂的事物的发展过程中，有许多的矛盾存在，其中必有一种是主要的矛盾，由于它的存在和发展规定或影响着其他矛盾的存在和发展。&quot;</p></blockquote><p><strong>通俗理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你同时有10件事要处理：</span></span>
<span class="line"><span>- 写报告（截止今天）</span></span>
<span class="line"><span>- 回邮件（截止今天）</span></span>
<span class="line"><span>- 开会（正在进行）</span></span>
<span class="line"><span>- 吃饭（饿了2小时）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主要矛盾 = 开会（正在进行，错过就没了）</span></span>
<span class="line"><span>次要矛盾 = 其他三件（可以推迟）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>抓住主要矛盾，其他迎刃而解</span></span></code></pre></div><p><strong>生活应用：</strong></p><table tabindex="0"><thead><tr><th>处境</th><th>主要矛盾</th></tr></thead><tbody><tr><td>公司快倒闭了</td><td>找到盈利模式</td></tr><tr><td>个人迷茫</td><td>找到核心竞争力</td></tr><tr><td>项目失败</td><td>找到关键失败原因</td></tr><tr><td>关系紧张</td><td>找到核心分歧点</td></tr></tbody></table><h4 id="方法二-分清矛盾的主要方面和次要方面" tabindex="-1">方法二：分清矛盾的主要方面和次要方面 <a class="header-anchor" href="#方法二-分清矛盾的主要方面和次要方面" aria-label="Permalink to &quot;方法二：分清矛盾的主要方面和次要方面&quot;">​</a></h4><p><strong>原文：</strong></p><blockquote><p>&quot;矛盾着的两方面中，必有一方面是主要的，他方面是次要的……事物的性质，主要地是由取得支配地位的矛盾的主要方面所规定的。&quot;</p></blockquote><p><strong>通俗理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一杯水（半满）：</span></span>
<span class="line"><span>- 主要方面 = 水的部分（所以我们说&quot;有水&quot;）</span></span>
<span class="line"><span>- 次要方面 = 空气的部分</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一个人的优点为主 → 整体评价：积极</span></span>
<span class="line"><span>一个人的缺点为主 → 整体评价：消极</span></span>
<span class="line"><span></span></span>
<span class="line"><span>领导看人：</span></span>
<span class="line"><span>- 看主流（主要方面）</span></span>
<span class="line"><span>- 不要求全责备（次要方面）</span></span></code></pre></div><h4 id="方法三-对抗性矛盾与非对抗性矛盾" tabindex="-1">方法三：对抗性矛盾与非对抗性矛盾 <a class="header-anchor" href="#方法三-对抗性矛盾与非对抗性矛盾" aria-label="Permalink to &quot;方法三：对抗性矛盾与非对抗性矛盾&quot;">​</a></h4><p><strong>原文：</strong></p><blockquote><p>&quot;对抗是矛盾斗争的一种形式，而不是矛盾斗争的一切形式。&quot;</p></blockquote><p><strong>通俗理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对抗性矛盾（如敌我矛盾）：</span></span>
<span class="line"><span>- 生死对立，不可调和</span></span>
<span class="line"><span>- 解决方式：一方消灭另一方</span></span>
<span class="line"><span>- 例：革命战争中敌我双方的矛盾</span></span>
<span class="line"><span></span></span>
<span class="line"><span>非对抗性矛盾（如人民内部矛盾）：</span></span>
<span class="line"><span>- 立场一致，方法分歧</span></span>
<span class="line"><span>- 解决方式：团结—批评—团结</span></span>
<span class="line"><span>- 例：同事之间的意见分歧</span></span></code></pre></div><p><strong>现实应用：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>处理人际冲突：</span></span>
<span class="line"><span>1. 先判断矛盾性质</span></span>
<span class="line"><span>   - 敌我矛盾（对抗性）→ 斗争为主</span></span>
<span class="line"><span>   - 人民内部矛盾（非对抗性）→ 团结为主</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 然后决定方式</span></span>
<span class="line"><span>   - 对抗性 → 坚守底线，以斗争求团结</span></span>
<span class="line"><span>   - 非对抗性 → 换位思考，求同存异</span></span></code></pre></div><hr><h2 id="四、两论合一-实践论-矛盾论的使用框架" tabindex="-1">四、两论合一：实践论+矛盾论的使用框架 <a class="header-anchor" href="#四、两论合一-实践论-矛盾论的使用框架" aria-label="Permalink to &quot;四、两论合一：实践论+矛盾论的使用框架&quot;">​</a></h2><h3 id="_4-1-解决问题的工作方法" tabindex="-1">4.1 解决问题的工作方法 <a class="header-anchor" href="#_4-1-解决问题的工作方法" aria-label="Permalink to &quot;4.1 解决问题的工作方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一步：调查研究（实践论的起点）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第二步：分析矛盾（矛盾论的起点）</span></span>
<span class="line"><span>  - 找主要矛盾</span></span>
<span class="line"><span>  - 找矛盾的主要方面</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第三步：制定方案</span></span>
<span class="line"><span>  - 针对主要矛盾下手</span></span>
<span class="line"><span>  - 集中力量</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第四步：试点执行（回到实践）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第五步：检验和修正（实践论的认识循环）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第六步：推广/调整</span></span></code></pre></div><h3 id="_4-2-分析任何事物的模板" tabindex="-1">4.2 分析任何事物的模板 <a class="header-anchor" href="#_4-2-分析任何事物的模板" aria-label="Permalink to &quot;4.2 分析任何事物的模板&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拿到一个新事物，用矛盾论分析：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 这个事物内部有哪些矛盾？</span></span>
<span class="line"><span>   - 哪一对是主要矛盾？</span></span>
<span class="line"><span>   - 矛盾的主要方面是什么？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 这个事物的矛盾有什么特殊性？</span></span>
<span class="line"><span>   - 区别于其他事物的本质特征是什么？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 这个事物的发展趋势是什么？</span></span>
<span class="line"><span>   - 矛盾将如何转化？</span></span>
<span class="line"><span>   - 旧矛盾解决后会出现什么新矛盾？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>拿到一个新问题，用实践论分析：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 这个问题从哪里来？（实践出发的根源）</span></span>
<span class="line"><span>2. 我对它的认识停留在感性还是理性？</span></span>
<span class="line"><span>3. 如何设计实践来验证我的判断？</span></span></code></pre></div><h3 id="_4-3-实例-用两论分析-风电行业投资" tabindex="-1">4.3 实例：用两论分析&quot;风电行业投资&quot; <a class="header-anchor" href="#_4-3-实例-用两论分析-风电行业投资" aria-label="Permalink to &quot;4.3 实例：用两论分析&quot;风电行业投资&quot;&quot;">​</a></h3><p><strong>背景：</strong> 风电产业链长、技术复杂、政策敏感。分析风电整机厂是否值得投资。</p><p><strong>矛盾分析：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主要矛盾：</span></span>
<span class="line"><span>- 需求侧：碳中和政策带来的长期确定性需求</span></span>
<span class="line"><span>- 供给侧：整机厂商同质化竞争、价格战</span></span>
<span class="line"><span></span></span>
<span class="line"><span>矛盾的主要方面：</span></span>
<span class="line"><span>- 政策支持（需求端）是主要的、决定性的</span></span>
<span class="line"><span>- 短期价格战是次要的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>特殊性分析：</span></span>
<span class="line"><span>- 风电区别于火电的核心矛盾：度电成本 vs 碳排放成本</span></span>
<span class="line"><span>- 随着技术进步，这个矛盾正在转化（风电成本持续下降）</span></span></code></pre></div><p><strong>实践检验：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>感性认识（表面现象）：</span></span>
<span class="line"><span>- 风电企业财报好看（营收增长）</span></span>
<span class="line"><span>- 政策文件很多（利好频出）</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>深入调研（理性认识）：</span></span>
<span class="line"><span>- 风机大型化趋势如何？</span></span>
<span class="line"><span>- 招标价格走势如何？</span></span>
<span class="line"><span>- 整机厂商毛利率真实情况？</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>实地验证：</span></span>
<span class="line"><span>- 去风电场考察</span></span>
<span class="line"><span>- 与行业专家交流</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>最终判断</span></span></code></pre></div><hr><h2 id="五、学习建议-怎么读《实践论》《矛盾论》" tabindex="-1">五、学习建议：怎么读《实践论》《矛盾论》 <a class="header-anchor" href="#五、学习建议-怎么读《实践论》《矛盾论》" aria-label="Permalink to &quot;五、学习建议：怎么读《实践论》《矛盾论》&quot;">​</a></h2><h3 id="_5-1-推荐阅读顺序-3遍法" tabindex="-1">5.1 推荐阅读顺序（3遍法） <a class="header-anchor" href="#_5-1-推荐阅读顺序-3遍法" aria-label="Permalink to &quot;5.1 推荐阅读顺序（3遍法）&quot;">​</a></h3><p><strong>第一遍（通读，30分钟）：</strong></p><ul><li>不用逐句理解，先通读全文</li><li>画出最触动你的3-5句话</li><li>标记不理解的地方</li></ul><p><strong>第二遍（精读，60分钟）：</strong></p><ul><li>每段用自己的话复述一遍</li><li>找一个现实例子套进去</li><li>做读书笔记</li></ul><p><strong>第三遍（结合实际）：</strong></p><ul><li>读完后找一件身边的事，用两论分析</li><li>写下分析过程</li><li>对照原文检验思路是否正确</li></ul><h3 id="_5-2-延伸阅读建议" tabindex="-1">5.2 延伸阅读建议 <a class="header-anchor" href="#_5-2-延伸阅读建议" aria-label="Permalink to &quot;5.2 延伸阅读建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>作者</th><th>与本文关系</th></tr></thead><tbody><tr><td>《大众哲学》</td><td>艾思奇</td><td>《实践论》《矛盾论》的通俗入门版</td></tr><tr><td>《矛盾论》《实践论》原文</td><td>毛泽东</td><td>必读原始文献</td></tr><tr><td>《通俗哲学》</td><td>韩树英</td><td>系统性哲学入门</td></tr><tr><td>《读懂中国优势》</td><td>主流媒体</td><td>两论在新时代的应用</td></tr><tr><td>《毛选》第一卷</td><td>毛泽东</td><td>两论之后的实践运用</td></tr></tbody></table><h3 id="_5-3-学习效果自测" tabindex="-1">5.3 学习效果自测 <a class="header-anchor" href="#_5-3-学习效果自测" aria-label="Permalink to &quot;5.3 学习效果自测&quot;">​</a></h3><p>回答以下三个问题，检验是否理解：</p><ol><li><strong>实践论角度：</strong> &quot;为什么听了那么多道理，依然过不好这一生？&quot;</li><li><strong>矛盾论角度：</strong> &quot;为什么同一个方法，张三用了有效，李四用了无效？&quot;</li><li><strong>综合应用：</strong> 用两论分析你当前面临的一个具体问题。</li></ol><hr><h2 id="六、常见误区澄清" tabindex="-1">六、常见误区澄清 <a class="header-anchor" href="#六、常见误区澄清" aria-label="Permalink to &quot;六、常见误区澄清&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确理解</th></tr></thead><tbody><tr><td>学了矛盾论就&quot;找茬&quot;</td><td>矛盾论是找主要矛盾，不是找所有人的茬</td></tr><tr><td>矛盾就是&quot;对立&quot;</td><td>矛盾 = 对立 + 统一，有斗争也有依存</td></tr><tr><td>实践就是&quot;多干活&quot;</td><td>实践是有目的的改造世界的活动，不是蛮干</td></tr><tr><td>认识一次就够了</td><td>认识是循环往复的过程，要不断深化</td></tr><tr><td>主要矛盾永远不变</td><td>主要矛盾会随着条件变化而转化</td></tr></tbody></table><hr><h2 id="七、两论的学习价值总结" tabindex="-1">七、两论的学习价值总结 <a class="header-anchor" href="#七、两论的学习价值总结" aria-label="Permalink to &quot;七、两论的学习价值总结&quot;">​</a></h2><h3 id="《实践论》教给你的" tabindex="-1">《实践论》教给你的 <a class="header-anchor" href="#《实践论》教给你的" aria-label="Permalink to &quot;《实践论》教给你的&quot;">​</a></h3><ul><li><strong>看问题从实际出发</strong>，而不是从书本出发</li><li><strong>用实践检验判断</strong>，而不是凭感觉决策</li><li><strong>认识是一个过程</strong>，不急于下结论</li></ul><h3 id="《矛盾论》教给你的" tabindex="-1">《矛盾论》教给你的 <a class="header-anchor" href="#《矛盾论》教给你的" aria-label="Permalink to &quot;《矛盾论》教给你的&quot;">​</a></h3><ul><li><strong>任何事物都有矛盾</strong>，没有矛盾的事物不存在</li><li><strong>要抓主要矛盾</strong>，眉毛胡子一把抓等于没抓</li><li><strong>具体问题具体分析</strong>，不存在万能公式</li></ul><h3 id="两者合起来" tabindex="-1">两者合起来 <a class="header-anchor" href="#两者合起来" aria-label="Permalink to &quot;两者合起来&quot;">​</a></h3><blockquote><p><strong>先调查研究找到矛盾，再在实践中检验和解决矛盾。</strong></p></blockquote><p>这就是毛泽东哲学的精髓：<strong>实事求是</strong>。</p><hr><p><em>整理：演员</em><em>参考来源：《毛泽东文集》第3卷（人民出版社1996年版）原文引用</em><em>最后更新：2026-06-16</em></p>`,115)])])}const g=s(l,[["render",e]]);export{u as __pageData,g as default};
